#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *A = (int*)malloc(N * sizeof(int));
    int *L = (int*)malloc(N * sizeof(int));
    int *R = (int*)malloc(N * sizeof(int));

    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }

    const int INF = 1000000000;

    int cur = INF;
    for (int i = 0; i < N; i++) {
        if (cur < INF) cur++;
        if (A[i] != -1 && A[i] < cur) cur = A[i];
        L[i] = cur;
    }

    cur = INF;
    for (int i = N - 1; i >= 0; i--) {
        if (cur < INF) cur++;
        if (A[i] != -1 && A[i] < cur) cur = A[i];
        R[i] = cur;
    }

    for (int i = 0; i < N; i++) {
        int ans = L[i] < R[i] ? L[i] : R[i];
        if (i > 0) putchar(' ');
        printf("%d", ans);
    }
    putchar('\n');

    free(A);
    free(L);
    free(R);
    return 0;
}
